import { fileFormats, type FileFormat } from '../../icons/file-names';
import './FileIcon.css';

/* The Figma "File format icon" set (src/icons/file, generated by `npm run icons`). Not inlined into the bundle. */
const files = import.meta.glob<string>('../../icons/file/*.svg', { eager: true, query: '?no-inline', import: 'default' });
const urlOf = (file: string) => files[`../../icons/file/${file}.svg`];
const known = new Set<string>(fileFormats.map(([key]) => key));

export { fileFormats, type FileFormat };

export type FileIconProps = {
  /** The file's extension or its name, such as `pdf` or `my_cv.pdf` */
  file: string;
  /** Figma Size: md-32px, lg-40px (the cards use 40) */
  size?: 32 | 40;
  className?: string;
};

/** The extension of a file name, in lower case: "Report.PDF" → pdf */
export const extensionOf = (file: string) => (file.includes('.') ? file.split('.').pop()! : file).toLowerCase();

/**
 * A file's format: a sheet with a coloured label (Figma "File format icon"). The light grey sheet has a dark-theme
 * version. A format the Figma set doesn't have (jpg, png, svg…) gets the same sheet with a neutral label and its
 * extension written on it. Decorative: the file name next to it says what it is.
 */
export function FileIcon({ file, size = 40, className = '' }: FileIconProps) {
  const ext = extensionOf(file);
  if (known.has(ext)) {
    const img = (name: string, theme: 'light' | 'dark') => (
      <img className={`grg-file-icon grg-file-icon--on-${theme} ${className}`} src={urlOf(name)} width={size} height={size} alt="" loading="lazy" decoding="async" />
    );
    return <>{img(ext, 'light')}{img(`${ext}-dark`, 'dark')}</>;
  }
  // The Figma sheet and label shapes, with the extension as text
  return (
    <svg className={`grg-file-icon grg-file-icon--any ${className}`} width={size} height={size} viewBox="0 0 40 40" aria-hidden="true">
      <path className="grg-file-icon__sheet" d="M11 0.75H27.3535L38.25 11.7373V34C38.25 36.8995 35.8995 39.25 33 39.25H11C8.10051 39.25 5.75 36.8995 5.75 34V6C5.75 3.10051 8.10051 0.75 11 0.75Z" fill="none" strokeWidth="1.5" />
      <path className="grg-file-icon__fold" d="M27 0L39 12H31C28.7909 12 27 10.2091 27 8V0Z" />
      <path className="grg-file-icon__label" d="M1 22C1 19.7909 2.79086 18 5 18H29C31.2091 18 33 19.7909 33 22V30C33 32.2091 31.2091 34 29 34H5C2.79086 34 1 32.2091 1 30V22Z" />
      <text className="grg-file-icon__text" x="17" y="29" textAnchor="middle">{ext.slice(0, 4)}</text>
    </svg>
  );
}
